function createDetailedPaymentsExcel() {
  const workbook = XLSX.utils.book_new();

  // Главный лист со всеми платежами
  const headers = [
    'Telegram ID',
    'Username',
    'Имя',
    'Фамилия',
    'Дата оплаты',
    'Сумма',
    'Звёзды',
    'Валюта',
    'Способ оплаты',
    'Эквив. в рублях',
    'Описание'
  ];

  const data = [headers];

  paymentsData.forEach(payment => {
    data.push([
      payment.telegram_id,
      payment.username || 'Не указан',
      payment.first_name || 'Не указано',
      payment.last_name || '',
      new Date(payment.payment_date).toLocaleDateString('ru-RU'),
      payment.amount,
      payment.stars,
      payment.currency,
      payment.payment_method || 'Не указан',
      payment.ruble_equivalent,
      payment.description
    ]);
  });

  const sheet = XLSX.utils.aoa_to_sheet(data);
  XLSX.utils.book_append_sheet(workbook, sheet, 'Все платежи');

  // Сводный лист
  const summarySheet = XLSX.utils.aoa_to_sheet([
    ['═══════════════════════════════════════════════════════════════'],
    ['            СВОДНАЯ ИНФОРМАЦИЯ                    '],
    ['         MetaMuse_Manifest_bot                      '],
    ['═══════════════════════════════════════════════════════════════'],
    [''],
    ['Всего реальных платежей:', paymentsData.length.toString(), '', ''],
    [''],
    ['По валютам:', '', '', ''],
    ['RUB платежи:', paymentsData.filter(p => p.currency === 'RUB').length.toString(), '', ''],
    ['XTR платежи:', paymentsData.filter(p => p.currency === 'XTR').length.toString(), '', ''],
    ['STARS платежи:', paymentsData.filter(p => p.currency === 'STARS').length.toString(), '', ''],
    [''],
    ['По способам оплаты:', '', '', ''],
    ['Robokassa:', paymentsData.filter(p => p.payment_method === 'Robokassa').length.toString(), '', ''],
    ['Telegram:', paymentsData.filter(p => p.payment_method === 'Telegram').length.toString(), '', ''],
    ['System:', paymentsData.filter(p => p.payment_method === 'System').length.toString(), '', ''],
    [''],
    ['═══════════════════════════════════════════════════════════════']
  ]);

  XLSX.utils.book_append_sheet(workbook, summarySheet, 'Сводка');

  return workbook;
}

const workbook = createDetailedPaymentsExcel();
const fileName = `MetaMuse_Manifest_bot_Детальные_платежи_${new Date().toISOString().split('T')[0]}.xlsx`;
XLSX.writeFile(workbook, fileName).then(() => console.log('xlsx written')).catch(e => { console.error(e); process.exitCode = 1 });

console.log('\n✅ Создана детальная таблица всех реальных платежей');
console.log('📄 Файл:', fileName);
console.log('📊 Всего записей:', paymentsData.length);